int out_fd, in_fd;
off64_t current_offset = 0;
size_t max_bytes = 8192;
ssize_t transferred;

// Transfer data using provided starting offset
transferred = sendfile64(
    out_fd,
    in_fd,
    &current_offset, // Pointer to offset (updated if successful)
    max_bytes
);

// Transfer data using the input file's internal position
transferred = sendfile64(
    out_fd,
    in_fd,
    NULL,            // NULL: Use/update in_fd's lseek offset
    max_bytes
);
